package org.springframework.samples.petclinic.acceptance;

import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.hamcrest.Matchers;
import org.junit.jupiter.api.Test;

import tools.jackson.databind.node.ObjectNode;

/**
 * Verifies the required-fields rule for creating an owner: a create must be rejected with 400 when
 * any of {@code firstName}, {@code lastName}, {@code address}, {@code city} or {@code telephone} is
 * missing (absent/null) or blank (empty or whitespace only), and the JSON body's {@code errors}
 * array must name each offending field.
 */
class OwnerRequiredFieldsTest extends AcceptanceBase {

	private static final String[] REQUIRED_FIELDS = {"firstName", "lastName", "address", "city", "telephone"};

	@Test
	void acceptsCompleteOwner() throws Exception {
		createOwner(ownerNode()).andExpect(status().is2xxSuccessful());
	}

	@Test
	void rejectsMissingFieldAndNamesIt() throws Exception {
		for (String field : REQUIRED_FIELDS) {
			ObjectNode o = ownerNode();
			o.remove(field);
			createOwner(o).andExpect(status().isBadRequest())
					.andExpect(jsonPath("$.errors").value(Matchers.hasItem(field)));
		}
	}

	@Test
	void rejectsNullFieldAndNamesIt() throws Exception {
		for (String field : REQUIRED_FIELDS) {
			ObjectNode o = ownerNode();
			o.putNull(field);
			createOwner(o).andExpect(status().isBadRequest())
					.andExpect(jsonPath("$.errors").value(Matchers.hasItem(field)));
		}
	}

	@Test
	void rejectsEmptyFieldAndNamesIt() throws Exception {
		for (String field : REQUIRED_FIELDS) {
			ObjectNode o = ownerNode();
			o.put(field, "");
			createOwner(o).andExpect(status().isBadRequest())
					.andExpect(jsonPath("$.errors").value(Matchers.hasItem(field)));
		}
	}

	@Test
	void rejectsBlankWhitespaceFieldAndNamesIt() throws Exception {
		for (String field : REQUIRED_FIELDS) {
			ObjectNode o = ownerNode();
			o.put(field, "   ");
			createOwner(o).andExpect(status().isBadRequest())
					.andExpect(jsonPath("$.errors").value(Matchers.hasItem(field)));
		}
	}

	@Test
	void listsEveryMissingFieldWhenSeveralAreAbsent() throws Exception {
		ObjectNode o = ownerNode();
		o.remove("address");
		o.put("city", "   ");
		createOwner(o).andExpect(status().isBadRequest())
				.andExpect(jsonPath("$.errors").value(Matchers.hasItems("address", "city")));
	}
}

